import{_ as s,C as n,c as a,o as d,a3 as r,G as o}from"./chunks/framework.Dokpd4od.js";const _=JSON.parse('{"title":"Purchase orders","description":"","frontmatter":{},"headers":[],"relativePath":"master/supply-chain/purchase/orders/purchase-orders.md","filePath":"master/supply-chain/purchase/orders/purchase-orders.md","lastUpdated":1791902625000}'),i={name:"master/supply-chain/purchase/orders/purchase-orders.md"};function l(g,t,c,h,p,u){const e=n("ImagePopup");return d(),a("div",null,[t[0]||(t[0]=r('<h1 id="purchase-orders" tabindex="-1">Purchase orders <a class="header-anchor" href="#purchase-orders" aria-label="Permalink to &quot;Purchase orders&quot;">​</a></h1><p>A purchase order (PO) is a confirmed order. You are now committed to buy, and Aureus plans the receipt. Small orders confirm at once. Big orders can wait for a manager to approve them.</p><blockquote><p><strong>In simple words:</strong> A purchase order is an RFQ you said yes to.</p></blockquote><p>Open <code>Purchase → Orders → Purchase Orders</code>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>Two options in <code>Purchase → Settings → Manage Orders</code> change what happens on confirm.</p><ul><li><strong>Purchase Order Approval:</strong> Turn on to hold big orders. Then set <strong>Minimum Amount</strong>. The default is 5000.</li><li><strong>Lock Confirmed Orders:</strong> Turn on to send confirmed orders straight to <strong>Locked</strong>.</li></ul><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2>',8)),o(e,{src:"/images1/purchase/po_list.png",alt:"Purchase Orders list showing PO/3, PO/4 and PO/5"}),t[1]||(t[1]=r('<p>The list shows orders in the <strong>Purchase Order</strong> and <strong>Locked</strong> states only.</p><ul><li><strong>Tabs:</strong> <strong>Default</strong>, <strong>My Orders</strong>, <strong>Starred</strong>, <strong>Waiting Bills</strong>, <strong>Bills Received</strong>.</li><li><strong>Group by:</strong> <strong>Vendor</strong>, <strong>Buyer</strong>, <strong>State</strong>, <strong>Created At</strong>, <strong>Updated At</strong>.</li><li><strong>New Order:</strong> starts a new order directly.</li></ul><h2 id="confirm-an-order" tabindex="-1">Confirm an order <a class="header-anchor" href="#confirm-an-order" aria-label="Permalink to &quot;Confirm an order&quot;">​</a></h2><p>Scenario: open <strong>PO/3</strong> from Consolidated Components, with 15 <strong>SSD 512GB</strong> and 10 <strong>Laptop Battery</strong>.</p><ol><li>Open the RFQ and click <strong>Confirm Order</strong>.</li></ol>',5)),o(e,{src:"/images1/purchase/po_confirm.png",alt:"RFQ with the Confirm Order button highlighted"}),t[2]||(t[2]=r('<ol start="2"><li>The state bar moves to <strong>Purchase Order</strong>. The <strong>Confirmation Date</strong> is filled.</li><li>The <strong>Receipts</strong> tab shows a new receipt, <strong>WH/IN/11</strong>. See <a href="./../../inventories/operations/receipts.html">Receipts</a>.</li></ol>',1)),o(e,{src:"/images1/purchase/po_confirmed.png",alt:"PO/3 in Purchase Order state with Create Bill, Lock and Cancel buttons"}),t[3]||(t[3]=r(`<h2 id="approval-workflow" tabindex="-1">Approval workflow <a class="header-anchor" href="#approval-workflow" aria-label="Permalink to &quot;Approval workflow&quot;">​</a></h2><p>With <strong>Purchase Order Approval</strong> on, the total decides what happens.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Total below Minimum Amount  → Purchase Order</span></span>
<span class="line"><span>Total at or above it, you are an approver → Purchase Order</span></span>
<span class="line"><span>Total at or above it, you are not → To Approve</span></span></code></pre></div><p>An approver is a user whose resource permission is <strong>Global</strong> or <strong>Group</strong>. When an approver clicks <strong>Confirm Order</strong> on a <strong>To Approve</strong> order, it moves on. It becomes <strong>Locked</strong> if <strong>Lock Confirmed Orders</strong> is on. Otherwise it becomes <strong>Purchase Order</strong>.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Receipts are planned only after approval, not while the order is <strong>To Approve</strong>.</p></div><h2 id="send-and-print" tabindex="-1">Send and print <a class="header-anchor" href="#send-and-print" aria-label="Permalink to &quot;Send and print&quot;">​</a></h2><ul><li><strong>Send PO By Email:</strong> emails the confirmed order with the PDF. The state does not change.</li><li><strong>Print PO:</strong> downloads the PDF.</li></ul><h2 id="lock-and-unlock" tabindex="-1">Lock and unlock <a class="header-anchor" href="#lock-and-unlock" aria-label="Permalink to &quot;Lock and unlock&quot;">​</a></h2><p>Locking protects a confirmed order from edits.</p><ul><li>Click <strong>Lock</strong> on a <strong>Purchase Order</strong>. It becomes <strong>Locked</strong>.</li><li>Click <strong>Unlock</strong> on a <strong>Locked</strong> order. It returns to <strong>Purchase Order</strong>.</li></ul>`,10)),o(e,{src:"/images1/purchase/po_locked.png",alt:"Locked order showing Unlock and Create Bill buttons"}),t[4]||(t[4]=r('<h2 id="cancel-an-order" tabindex="-1">Cancel an order <a class="header-anchor" href="#cancel-an-order" aria-label="Permalink to &quot;Cancel an order&quot;">​</a></h2><p>Click <strong>Cancel</strong>. The state becomes <strong>Canceled</strong> and planned receipts are canceled. Aureus refuses in two cases.</p><ul><li><strong>The order cannot be canceled since they have receipts that are already done.</strong> Return the goods first.</li><li><strong>The order cannot be canceled. You must first cancel their related vendor bills.</strong> Cancel the bills, then try again.</li></ul>',3)),o(e,{src:"/images1/purchase/po_cancel_refused.png",alt:"Notification refusing to cancel because a receipt is already done"}),t[5]||(t[5]=r('<h2 id="set-to-draft" tabindex="-1">Set to Draft <a class="header-anchor" href="#set-to-draft" aria-label="Permalink to &quot;Set to Draft&quot;">​</a></h2><p>A <strong>Canceled</strong> order shows <strong>Set to Draft</strong>. Click it to return the order to <strong>RFQ</strong>. You can edit and send it again.</p><h2 id="quantity-rules" tabindex="-1">Quantity rules <a class="header-anchor" href="#quantity-rules" aria-label="Permalink to &quot;Quantity rules&quot;">​</a></h2><p>After confirmation, Aureus protects what you already received.</p><table tabindex="0"><thead><tr><th>Message</th><th>Cause</th></tr></thead><tbody><tr><td><strong>Cannot Reduce Quantity</strong></td><td>You set a quantity below the <strong>Received</strong> quantity.</td></tr><tr><td><strong>Cannot Delete Product</strong></td><td>You removed a line from a confirmed order.</td></tr><tr><td><strong>Quantity Exceeds Blanket Order Limit</strong></td><td>The line is above the linked blanket order.</td></tr></tbody></table><p>Raising a quantity is allowed. The planned receipt grows with it.</p><h2 id="actions-and-statuses" tabindex="-1">Actions and statuses <a class="header-anchor" href="#actions-and-statuses" aria-label="Permalink to &quot;Actions and statuses&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Button</th><th>Shown in</th><th>Result</th></tr></thead><tbody><tr><td><strong>Confirm Order</strong></td><td><strong>RFQ</strong>, <strong>RFQ Sent</strong>, <strong>To Approve</strong></td><td><strong>Purchase Order</strong>, <strong>Locked</strong> or <strong>To Approve</strong></td></tr><tr><td><strong>Send PO By Email</strong></td><td><strong>Purchase Order</strong></td><td>Emails the vendor. No state change.</td></tr><tr><td><strong>Print PO</strong></td><td><strong>Purchase Order</strong></td><td>Downloads the PDF.</td></tr><tr><td><strong>Create Bill</strong></td><td><strong>Purchase Order</strong>, <strong>Locked</strong></td><td>Makes a vendor bill. See <a href="./vendor-bills.html">Vendor bills</a>.</td></tr><tr><td><strong>Lock</strong></td><td><strong>Purchase Order</strong></td><td><strong>Locked</strong></td></tr><tr><td><strong>Unlock</strong></td><td><strong>Locked</strong></td><td><strong>Purchase Order</strong></td></tr><tr><td><strong>Cancel</strong></td><td>Not <strong>Locked</strong></td><td><strong>Canceled</strong>, unless refused</td></tr><tr><td><strong>Set to Draft</strong></td><td><strong>Canceled</strong></td><td><strong>RFQ</strong></td></tr><tr><td><strong>Delete</strong></td><td>Most states</td><td>Removes the order.</td></tr></tbody></table><h2 id="see-also" tabindex="-1">See also <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;See also&quot;">​</a></h2><ul><li><a href="./">Orders overview</a></li><li><a href="./quotations.html">Quotations</a></li><li><a href="./../../inventories/operations/receipts.html">Receipts</a></li><li><a href="./../get-started/purchase-settings.html">Purchase settings</a></li></ul>',10))])}const f=s(i,[["render",l]]);export{_ as __pageData,f as default};
